    if qid in exp_bcs:
        item['explanation'] = exp_bcs[qid]
    else:
        item['explanation'] = "কম্পিউটার ও তথ্যপ্রযুক্তির মৌলিক নীতিমালার ওপর ভিত্তি করে এই প্রশ্নের উত্তরটি সঠিক।"

